  "Classique : dès une erreur ou une aide. Storm : après une mauvaise réponse.": "클래식: 실수나 도움을 받은 후 태풍: 잘못된 답변에 따라.",
  "Les copies existantes et leurs annotations sont conservées, sans doublon dans la même base. Les anciennes tentatives ne sont pas copiées rétroactivement.": "기존의 복사본과 해석은 동일한 데이터베이스에 복사본이 없도록 보존된다. 과거 시도는 후진적으로 복사되지 않습니다.",
  "La solution du puzzle est indisponible. Recharge la page.": "체스 퍼즐 솔루션은 사용할 수 없습니다. 페이지를 다시 로드하세요.",
  "Puzzles à revoir": "재검토할 수 있는 체스 퍼즐",
  "Exercice ajouté à la base. Le puzzle est conservé.": "데이터베이스에 추가된 운동 당신의 체스 퍼즐은 보존되어 있습니다.",
  "La solution est préremplie. Tu peux la modifier ou ajouter des variantes.": "용액은 미리 채워져 있습니다. 편집하거나 변형을 추가할 수 있습니다.",
  "Revoir les puzzles joués": "셰익스피어 퍼즐",
  "La solution fournie pour cet exercice est invalide.": "제공된 운동 용액은 무효입니다.",
  "La solution ne commence pas à la position choisie.": "해결책은 선택한 위치에서 시작되지 않습니다.",
  "Dès une erreur, un indice ou une solution affichée, le puzzle est ajouté à la base choisie. Cela s’applique aussi au puzzle classique en cours.": "실수, 암시 또는 밝혀진 해법 후, 체스 퍼즐은 선택한 데이터베이스에 추가됩니다. 이것은 현재의 고전적인 체스 퍼즐에도 적용됩니다.",
  "Crée d’abord une base d’étude dans la bibliothèque.": "먼저 도서관에서 연구 데이터베이스를 만들어 보세요.",
  "Les copies existantes et leurs annotations sont conservées. L’historique et Puzzle Storm ne sont pas copiés automatiquement.": "기존의 복사본과 해석은 보존되어 있습니다. 과거 시도와 체스 퍼즐 Storm는 자동으로 복사되지 않습니다.",
  "Réglages des puzzles enregistrés.": "체스 퍼즐 설정을 저장했습니다.",
