  "La date doit suivre AAAA.MM.JJ ; les éléments inconnus peuvent être remplacés par des ?.": "날짜에 YYYY.MM.DD를 사용하십시오. 알려지지 않은 부분은 ?.로 대체될 수 있습니다.",
