  "Le mois ou le jour de la date est invalide.": "달이나 날은 유효하지 않습니다.",
  "Le suivi de lecture est désactivé pour cette base.": "이 데이터베이스에 대한 읽기 추적은 비활성화되어 있습니다.",
  "Action de lecture invalide.": "유효하지 않은 읽기 액션",
  "Chemin de coup invalide.": "비효율적인 체스 이동 경로",
  "Le temps de lecture doit être compris entre 0 et 60 secondes.": "읽기 시간은 0초에서 60초 사이에 있어야 합니다.",
  "Identifiant de suivi invalide.": "유효하지 않은 추적 ID",
  "Un identifiant est nécessaire pour enregistrer le temps de lecture.": "읽기 시간을 기록하기 위해 주민등록증이 필요합니다.",
  "La partie a changé : recharge-la avant de poursuivre le suivi de lecture.": "체스 게임은 바뀌었습니다. 계속 읽기 전에 다시 로드하세요.",
  "Le signet a changé sur un autre écran. Recharge son état.": "다른 화면에서 북마크가 변경되었습니다. 상태를 재충전하세요.",
  "Cette position ne correspond plus à la partie enregistrée.": "이 위치는 더 이상 저장된 체스 게임과 일치하지 않습니다.",
  "Choisis lu ou non lu pour cette base.": "이 데이터베이스에서 읽거나 읽지 않는 것을 선택하십시오.",
  "Active le suivi de lecture dans les réglages de cette base.": "이 데이터베이스의 설정에서 읽기 추적을 가능하게 합니다.",
