  "Identifiant de stockage invalide.": "유효하지 않은 저장 ID",
  "Cette grande base est introuvable.": "이 참조 데이터베이스는 발견되지 않았다.",
  "Choisis une base d’étude pour sauvegarder ou réviser cette partie. La grande base conserve son import original.": "이 체스 게임을 저장하거나 검토하기 위해 연구 데이터베이스를 선택하십시오. 참고 데이터베이스는 원래의 수입을 유지합니다.",
  "Indique le chemin complet du PGN sur la machine qui héberge ChessGym.": "ChessGym를 호스팅하는 기기에서 전체 PGN 경로를 입력합니다.",
  "Choisis un fichier local existant .pgn ou .pgn.zst, avec son chemin complet.": ".pgn 또는 .pgn.zst 로컬 파일의 전체 경로를 선택하십시오.",
  "Option d’import inconnue.": "알려지지 않은 수입 옵션",
  "La limite doit être un nombre entier de parties, ou vide pour tout importer.": "제한은 체스 게임의 정수 수, 또는 모든 것을 수입하기 위해 공허해야 합니다.",
  "Choisis un encodage PGN pris en charge.": "지원되는 PGN 코딩을 선택하십시오.",
  "Un import de grande base est déjà en cours. Termine-le ou mets-le en pause avant d’en lancer un autre.": "이미 기준 수입이 진행중입니다. 다른 것을 시작하기 전에 끝내고 멈추십시오.",
  "Mets l’import en pause avant de supprimer cette base.": "이 데이터베이스를 삭제하기 전에 수입을 중단하십시오.",
  "Un import est déjà en cours. Mets-le en pause avant de créer le suivant.": "이미 수입이 진행중입니다. 다음을 만들기 전에 잠시 멈추세요.",
  "Cette partie dépasse 20 Mo après conversion du texte en UTF-8.": "이 체스 게임은 UTF-8으로 변환된 후 20 MB를 초과합니다.",
  "Le PGN contient des coups ignorés par le lecteur.": "PGN은 파서에서 무시된 체스 동작을 포함합니다.",
  "Le nombre maximal de parties doit être positif.": "최대의 체스 게임이 긍정적이어야 합니다.",
  "La taille des lots doit être comprise entre 1 et 5 000.": "배트 크기는 1~5,000이어야 합니다.",
  "Encodage non pris en charge. Choisis UTF-8, Windows-1252 ou Latin-1.": "지원되지 않은 코딩 UTF-8, Windows-1252 또는 라틴-1을 선택하세요.",
  "Le cache d’import doit être un entier compris entre 64 et 4 096 Mio.": "수입 캐시는 64에서 4,096 MiB 사이의 정수일 수 있어야 합니다.",
  "Le tri des positions doit être activé ou désactivé.": "위치 분류는 활성화되거나 비활성화되어야 합니다.",
  "Choisis un fichier .pgn ou .pgn.zst.": ".pgn 또는 .pgn.zst 파일을 선택하세요.",
  "Décalage de page invalide.": "유효하지 않은 페이지 오프셋",
  "Une page contient entre 1 et 250 parties.": "한 페이지에는 1~250개의 체스 게임이 있습니다.",
