  "Réglages du moteur non reconnus.": "인식되지 않은 체스 엔진 설정.",
  "Choisis une durée ou une profondeur de calcul.": "계산 시간이나 깊이를 선택하세요.",
  "Partie source introuvable.": "출처 체스 게임은 발견되지 않았습니다.",
