  "La partie enregistrée a changé. Recharge-la avant de vérifier son répertoire.": "저장된 체스 게임은 바뀌었습니다. 개막 레퍼토리를 확인하기 전에 다시 로드하세요.",
  "Le PGN ne peut pas être lu.": "PGN은 읽을 수 없습니다.",
