  "La ligne source a changé. Vérifie à nouveau sa compatibilité.": "소스 라인은 바뀌었습니다. 다시 호환성을 확인해 보세요.",
  "Le répertoire a changé. Vérifie à nouveau la ligne avant de l’ajouter.": "개막 레퍼토리는 바뀌었습니다. 추가하기 전에 라인을 다시 확인하세요.",
