  "Identifiant de brouillon invalide.": "유효하지 않은 신분함",
  "Indique la révision du brouillon à enregistrer.": "저장하기 위해 초안의 개정을 제공하십시오.",
  "Ce brouillon a changé sur un autre appareil. Conserve ton brouillon local avant de choisir la version à reprendre.": "이 초안은 다른 장치에서 변경되었습니다. 어떤 버전을 재개할지 선택하기 전에 지역 드래프트를 보관하세요.",
  "Le brouillon doit contenir un objet de données et sa révision.": "초안에는 데이터 객체와 그 개정 내용이 포함되어야 합니다.",
  "Ce brouillon dépasse la limite de 2 Mo. Sauvegarde la partie dans une base.": "이 초안은 2 MB의 한계를 초과합니다. 체스 게임을 데이터베이스에 저장하세요.",
  "Les brouillons occupent tout l’espace prévu. Sauvegarde ou supprime un brouillon avant de continuer.": "드래프트 저장소는 가득합니다. 계속하기 전에 드래프트를 저장하거나 삭제하십시오.",
  "Les données du brouillon sont invalides.": "유효하지 않은 자료 초안",
  "Objectif de séance inconnu.": "미지의 세션 목표.",
  "Réglage de journée d’étude inconnu.": "연구 날 설정은 알려지지 않았습니다.",
