  "Aucune coche = toutes les cadences, y compris les inconnues.": "선택은 없습니다 = 알려지지 않은 것을 포함하여 모든 시간 제어",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo은 PGN에서 왔으며 두 플레이어의 범위 내에서 있어야합니다. Elo를 제외한 체스 게임은 한계가 설정되면 제외된다. 실종되거나 인정되지 않은 PGN 시간 제어 장치들은 \"알지 않는다\". 이러한 체스 게임은 \"불명\"이 선택되지 않는 한 시간 컨트롤을 선택하면 제외됩니다.",
  ": indique un nombre valide pour la borne Elo.": ": Elo 라인 시 유효한 번호를 입력합니다.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": 0에서 4000까지의 전수 Elo을 입력하거나 연결된 부분을 빈 상태로 남겨두십시오.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": 최소 Elo은 최대 Elo를 초과할 수 없습니다.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "데이터베이스를 만들고 도서관에 PGN 체스 게임을 가져오십시오.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess 마스터에는 Elo 또는 시간 조절 필터가 없습니다. 마스터 컬렉션을 필터링하려면 메가 데이터베이스와 같은 수입 데이터베이스를 선택하십시오.",
  "Source principale": "주요 출처",
  "Mes bases PGN": "제 PGN 데이터베이스",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "오직 주선 체스 움직임만 계산된다. 분석 변이는 통계를 부풀려 하지 않는다.",
  "Référence dans chaque ligne": "각 줄에 대한 참조",
  "Comparer avec": "비교",
  "Mes bases de référence": "내 참조 데이터베이스",
  "Aucune référence": "참고 자료가 없습니다",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "이 필터는 주요 데이터베이스로부터 독립적입니다. 비율은 선택된 참조의 이 위치에서 체스 이동 빈도를 나타냅니다.",
  "Probabilité de rencontre": "만남의 가능성은",
  "Afficher la probabilité de la ligne": "선 확률을 표시",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "탐사선수에서 직접 당신의 편을 선택하세요. 상대방의 답변만 중요하고, 당신의 체스 움직임은 가정됩니다. 이 추정치는 표시된 변수와 선택된 데이터베이스 필터를 따른다. 다이어그램에서 출발하는 PGN의 경우, 그것은 그 출발 위치에 달려 있습니다.",
  "Mode d’analyse": "분석 모드",
  "Rapide (~250 ms par coup)": "빠른 (~ 250 ms 한 체스 동작)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "더 높은 깊이는 분석을 정밀화시키고 더 오래 걸립니다. 8에서 30까지, 체스 움직임마다 10초의 제한이 있습니다. 목표가 달성되지 않으면 ≈은 결과를 표시합니다. 실제 깊이를 보기 위해 떠납니다.",
  "Chargement de la connexion…": "로딩 연결...",
  "Connexion indisponible.": "연결이 불가능해요",
  "Jeton fourni par le serveur.": "서버에 의해 제공된 토큰",
