  "Choisis au moins une cadence et une tranche de classement.": "최소 한 번의 제어 및 평가 범위를 선택하십시오.",
  "Référence Lichess : choisis au moins une cadence et une tranche de classement.": "Lichess 참조: 적어도 한 번의 제어 및 평가 범위를 선택하십시오.",
