  "≈ 1 sur": "≈ 1 /",
  "Estimation selon la base, la cadence et le niveau sélectionnés. Seules les réponses adverses sont multipliées ; tes propres coups sont supposés joués.": "선택된 데이터베이스, 시간 제어 및 등급에 기초한 추정 상대방의 답변만 곱합니다. 자신의 체스 움직임을 가정합니다.",
  "Calcul depuis la position de départ du PGN, pas depuis le début d’une partie.": "PGN의 출발 위치에서 계산되며, 체스 경기의 시작이 아닙니다.",
