  ", dont des diagrammes": ", 다이어그램을 포함한",
  ". Chaque probabilité suppose son départ déjà atteint ; elles ne s’additionnent pas entre ces départs.": ". 각 확률은 출발 위치가 달성되었다고 가정합니다. 출발 위치에서 확률을 더할 수 없습니다.",
  "Ce répertoire commence sur un diagramme : les probabilités supposent cette position déjà atteinte.": "이 개막 레퍼토리는 다이어그램에서 시작됩니다. 확률은 이미 이 위치에 도달했다고 가정합니다.",
  "Aucune lacune trouvée dans les chemins examinés avec ces réglages.": "이 설정을 통해 조사된 경로에서 빈틈이 발견되지 않았습니다.",
  "La limite de cette exploration est atteinte. Affine les réglages pour réduire le nombre de positions à examiner.": "탐색의 한계가 달성되었습니다. 점검할 수 있는 포지션 수를 줄이기 위해 설정을 정비한다.",
