  "Les données disponibles ne permettent pas encore de compléter le bilan. Ajuste les filtres ou réessaie plus tard.": "사용 가능한 데이터는 아직 보고서를 완성할 수 없습니다. 필터를 조정하거나 나중에 다시 시도하십시오.",
