  "La fréquence utilise la dernière exploration « À compléter » de ce répertoire. Les reprises et les anciens retards restent prioritaires. Sans statistiques, l’ordre habituel est conservé.": "Frequency는 이 개막 레퍼토리의 최신 \"Coverage gaps\" 스캔을 사용합니다. 재교육과 오래된 늦은 카드들은 우선 순위를 유지합니다. 통계가 없으면 일반적인 순서가 유지됩니다.",
