  "La position de cet exercice a changé. La partie complète est ouverte à son point de départ.": "이 운동의 위치가 바뀌었습니다. 전체 체스 게임은 시작 위치에서 열려 있습니다.",
  "La séance de révision n’est plus active.": "검토 세션은 더 이상 활동하지 않습니다.",
  "Sauvegardes": "백업",
  "La sauvegarde personnelle contient tes bases de travail, annotations, réglages, brouillons et historique de révision. Elle exclut les grandes bases de référence.": "개인 백업은 연구 데이터베이스, 해설, 설정, 드래프트 및 검토 역사를 포함합니다. 그것은 큰 참조 데이터베이스를 배제합니다.",
  "Ce serveur propose la sauvegarde complète, qui contient également les grandes bases de référence.": "이 서버는 전체 백업을 제공하며, 또한 큰 참조 데이터베이스를 포함합니다.",
