  "Espacement actuel des cartes actives déjà vues et encore soumises à répétition. Les cartes maîtrisées sont exclues.": "이미 볼 수 있고 여전히 반복될 예정인 활성 카드의 현재 간격 마스터 카드는 제외됩니다.",
