  "Agrandir l’échiquier": "셰어보드 확대",
  "Maîtrise automatique · après un intervalle de plus de (jours)": "자동 마스터링 · (일) 보다 긴 간격 후에",
  "S’applique à toutes les bases, y compris aux cartes déjà au-delà de ce seuil : elles deviennent immédiatement maîtrisées et ne reviennent plus en révision. Les cartes déjà maîtrisées restent inchangées.": "이 문턱을 넘어선 카드를 포함한 모든 데이터베이스에 적용됩니다. 그들은 즉시 마스터되고 재검토에 반환되지 않습니다. 이미 숙달된 카드들은 변하지 않습니다.",
  "Valeurs initiales des nouvelles bases": "새로운 데이터베이스의 초기 값",
  "Chaque base conserve ensuite ses propres réglages. Modifier ces valeurs ne change pas les bases existantes.": "각 데이터베이스가 자신의 설정을 유지합니다. 이러한 값을 변경하면 기존 데이터베이스를 변경하지 않습니다.",
