  "{count} exercice maîtrisé, conservé dans les appris, sans nouvelles révisions.": "{count}은 숙련된 운동이며, 더 이상의 검토 없이 학습된 대로 유지된다.",
  "{count} exercices maîtrisés, conservés dans les appris, sans nouvelles révisions.": "{count} 숙련된 연습, 더 이상의 검토 없이 배운 대로 유지됩니다.",
  "Progression des intervalles": "간격 성장",
  "Pour une carte déjà vue, le délai précédent est multiplié selon ta réponse, puis limité par les minimums et le maximum de sa base. Manqué repart du délai court réglé dans la base.": "이전에 볼 수 있는 카드의 경우, 이전 간격은 답변에 따라 곱하고, 데이터베이스의 최소 및 최대 간격으로 제한됩니다. 데이터베이스의 짧은 간격에서 다시 시작됩니다.",
  "Difficile · multiplicateur": "단단한 · 곱하기",
