  "{count} aide": "{count} 팁",
  "{count} aides": "{count} 팁",
  "Aucun brouillon pour cet échiquier intact. Ouvrir le travail conservé.": "이 미치지 않은 체스보드에는 드래프트가 없습니다. 저장된 작업을 열어.",
  "Le brouillon a changé. Rouvre la liste avant de le supprimer.": "드래프트가 바뀌었습니다. 삭제하기 전에 목록을 다시 열십시오.",
  "La synchronisation est indisponible. Le brouillon reste conservé.": "동기화가 불가능해요 미술은 여전히 보존되어 있습니다.",
  "Résous le conflit avant de supprimer ce brouillon.": "이 초안을 삭제하기 전에 갈등을 해결하세요.",
  "Le compte ouvert a changé.": "로그인 계좌가 변경되었습니다.",
  "Supprimer ce brouillon et ses annotations non enregistrées ? L’échiquier actuel sera réinitialisé; les parties enregistrées dans les bases sont conservées.": "이 드래프트와 그 저장되지 않은 해설을 삭제하세요? 현재의 체스 보드는 리셋됩니다. 데이터베이스에 저장된 체스 게임이 유지됩니다.",
  "Supprimer ce brouillon et ses annotations non enregistrées ? Les parties enregistrées dans les bases sont conservées.": "이 드래프트와 그 저장되지 않은 해설을 삭제하세요? 데이터베이스에 저장된 체스 게임은 보관됩니다.",
  "Brouillon supprimé.": "초안 삭제",
  "La suppression est incomplète. Cette copie reste conservée sur cet appareil.": "삭제는 불완전합니다. 이 복사본은 여전히 이 장치에 저장되어 있습니다.",
  "Ordre des nouveaux exercices": "새로운 훈련 순서",
