  "Ouvre la base pour modifier cette sélection.": "이 선택지를 편집하기 위해 데이터베이스를 열십시오.",
  "Préparation de la liste…": "리스트를 준비하고...",
  "Un brouillon local est illisible. Sa copie est conservée; les autres brouillons restent disponibles.": "지역 드래프트는 읽을 수 없습니다. 이 책 의 복사본 은 보존 되었으며, 그 밖 의 초안 은 여전히 사용 할 수 있다.",
