  "Ces moteurs fonctionnent sur la machine qui héberge ChessGym. Le choix s’applique aux prochains calculs.": "이 체스 엔진들은 ChessGym을 탑재하는 기계에서 작동합니다. 당신의 선택은 앞으로의 계산에 적용됩니다.",
