  "Active les révisions dans les réglages d’une base pour préparer ta séance.": "회의를 준비하기 위해 데이터베이스의 설정에서 리뷰를 활성화하십시오.",
  "Actualiser l’aperçu": "업데이트 미리보기",
  "Commencer la séance": "세션 시작",
  "Composition de la séance": "회의 구성",
  "Composition proposée": "제안된 회의",
  "{count} exercices pour cette séance": "이 세션에 대한 {count} 연습",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les paramètres et limites de chaque base sont conservés.": "개인적인 실수와 실패한 체스 퍼즐은 이미 활발한 데이터베이스에 있는 연습에서 나옵니다. 각 데이터베이스의 설정과 제한은 유지됩니다.",
  "Actualise l’aperçu pour vérifier cette sélection.": "이 선택지를 확인하기 위해 미리보기를 업데이트하십시오.",
  "Préparation de l’aperçu…": "미리보기를 준비하고 있어요",
  "La séance respecte les échéances et les limites quotidiennes.": "회의는 날짜와 일일 제한을 준수합니다.",
  "Aucun exercice disponible pour cette sélection aujourd’hui.": "오늘날 이 선택에 대한 연습은 없습니다.",
  "Préparation de la séance…": "준비 세션...",
  "Vérifier et reprendre": "확인 및 재개",
  "La création de la séance est en attente de confirmation. Réessaie pour retrouver la même séance.": "회의를 만드는 것은 확인을 기다리고 있습니다. 같은 시션을 다시 시도해보세요.",
  "La séance est prête. Termine le coup en cours pour l’ouvrir.": "회의가 준비됐습니다. 현재 셰익스피어 움직임을 끝내고 그것을 열어야 합니다.",
  "Mettre la séance en pause": "휴식 세션",
  "Conserver dans les appris avec des rappels d’entretien espacés": "간편한 유지보수 상기서로 배운 대로 유지하세요",
  "Marquer comme maîtrisé avec entretien des acquis": "유지보수 리뷰에 의해 숙달된 마크",
  "{count} exercices maîtrisés. Des rappels d’entretien espacés préservent ces acquis.": "{count} 연습을 익혔습니다. 간격적인 유지보수 검토는 그들을 유지하는 데 도움이 됩니다.",
  "Les prochaines reprises respectent les réglages de chaque base.": "앞으로의 리뷰는 각 데이터베이스의 설정을 존중합니다.",
  "Entretenir les cartes maîtrisées": "숙련된 카드를 유지하세요",
  "Rappel d’entretien · jours": "유지보수 간격 ·일",
  "Maximum de rappels par jour": "하루 최대 상기",
  "Les acquis restent conservés. Les premiers rappels des anciennes cartes sont répartis dans le temps, sous ce plafond quotidien. Une erreur remet la carte en apprentissage.": "당신의 발전은 보존되어 있습니다. 기존 카드에 대한 초기 상기제는 이 매일의 한계 내에서 시간이 지남에 따라 분산됩니다. 실수로 배움의 카드가 돌아옵니다.",
  "Les cartes au-delà de ce seuil deviennent maîtrisées. Leur historique est conservé et les rappels suivent les réglages d’entretien ci-dessous.": "이 문턱을 넘어서는 카드는 숙달됩니다. 그들의 역사는 보존되어 있으며 상기물은 아래의 유지보수 설정을 따르고 있습니다.",
  "{count} rappels d’entretien dus": "{count} 유지보수 검토가 필요한",
  " cartes actives. Les rappels des cartes maîtrisées suivent tes réglages d’entretien. ": " 액티브 카드 마스터 카드 리모델링은 유지보수 설정을 따라합니다. ",
  "Aucun exercice disponible. Les cartes maîtrisées suivent leurs rappels d’entretien. Vérifie les parties sélectionnées et les réponses enregistrées dans cette base.": "운동은 없습니다. 마스터 카드들은 유지보수 스케줄을 따르죠. 선택된 체스 게임을 확인하고 이 데이터베이스에서 저장된 답변을 확인합니다.",
