  "Aucune durée connue sur la période précédente": "이전 기간에 확인된 시간이 없음",
  "Durées connues uniquement": "확인된 시간만",
  "Choisis une période valide de 730 jours au maximum.": "최대 730일 이내의 올바른 기간을 선택하세요.",
  "Sélectionne une activité pour explorer ton temps.": "시간 내역을 살펴볼 활동을 선택하세요.",
  "Aucune durée mesurée sur cette période. Les nouvelles activités apparaîtront ici automatiquement.": "이 기간에는 측정된 시간이 없습니다. 새 활동은 여기에 자동으로 표시됩니다.",
  "{count} activité(s) ont une durée inconnue. Elles ne sont pas comptées comme zéro.": "활동 {count}개의 시간을 알 수 없습니다. 이 시간을 0으로 계산하지 않습니다.",
  "{count} durée(s) inconnue(s)": "시간을 알 수 없는 항목 {count}개",
  "Le temps au fil des jours": "날짜별 시간 추이",
  "Chaque couleur représente une activité. Survole une barre pour voir sa durée.": "각 색상은 하나의 활동을 나타냅니다. 막대에 마우스를 올리면 시간을 볼 수 있습니다.",
  "Temps enregistré par période et par activité": "기간 및 활동별 기록 시간",
