  "Répartition du temps par activité": "활동별 시간 분포",
  "au total": "총합",
  "La régularité en un regard": "한눈에 보는 꾸준함",
  "Une case par jour. Plus la couleur est intense, plus tu as consacré de temps.": "한 칸이 하루를 나타냅니다. 색상이 진할수록 더 많은 시간을 보냈습니다.",
  "Calendrier du temps consacré": "활동 시간 달력",
  "Ton rythme dans la semaine": "요일별 훈련 패턴",
  "Temps moyen pour chaque jour de la semaine, jours sans activité inclus.": "활동하지 않은 날을 포함한 요일별 평균 시간입니다.",
  "Voir les données": "데이터 보기",
  "Durées enregistrées pour les activités sélectionnées": "선택한 활동의 기록 시간",
  "Stockfish sert à l’analyse et au jeu classique; Maia reproduit un jeu humain. Les bases de référence et de puzzles restent facultatives.": "Stockfish는 분석과 일반 대국에 사용되고, Maia는 사람의 플레이를 재현합니다. 참고 및 퍼즐 데이터베이스는 선택 사항입니다.",
  "Quand ChessGym est ouvert, les versions compatibles des moteurs et les bases installées compatibles sont vérifiées puis actualisées. Les éditions Lumbra se téléchargent séparément sur leur site. Les téléchargements peuvent être volumineux.": "ChessGym이 실행 중이면 호환되는 엔진 버전과 설치된 데이터베이스를 확인하고 업데이트합니다. Lumbra 버전은 해당 웹사이트에서 별도로 다운로드합니다. 다운로드 용량이 클 수 있습니다.",
  "Licence : {license}": "라이선스: {license}",
  "Conditions de licence": "라이선스 조건",
  "Par Michael Jansen. Usage non commercial avec attribution; une licence distincte est nécessaire pour un usage commercial.": "제작: Michael Jansen. 출처를 표시한 비상업적 이용만 가능합니다. 상업적 이용에는 별도 라이선스가 필요합니다.",
  "Télécharge cette édition sur le site Lumbra, accepte sa licence, puis indique le fichier .7z ou .pgn présent sur le PC ou serveur de ChessGym.": "Lumbra 웹사이트에서 이 버전을 다운로드하고 라이선스에 동의한 다음, ChessGym을 실행하는 PC 또는 서버에 있는 .7z 또는 .pgn 파일의 경로를 입력하세요.",
  "Télécharger sur Lumbra": "Lumbra에서 다운로드",
  "Chemin du fichier téléchargé sur le serveur": "서버에 다운로드한 파일의 경로",
  "Ex. C:\\Téléchargements\\Lumbra.7z": "예: C:\\Downloads\\Lumbra.7z",
  "Utiliser comme référence de maîtres": "마스터 대국 참고 데이터베이스로 사용",
  "Importer la base téléchargée": "다운로드한 데이터베이스 가져오기",
  "Les nouvelles éditions Lumbra se téléchargent sur leur site; les mises à jour automatiques ne les remplacent pas.": "새 Lumbra 버전은 해당 웹사이트에서 다운로드하세요. 자동 업데이트로는 교체되지 않습니다.",
  "Taille de l’archive : environ {size} Mo": "압축 파일 크기: 약 {size}MB",
  "Indique le chemin du fichier Lumbra téléchargé.": "다운로드한 Lumbra 파일의 경로를 입력하세요.",
  "Lumbra OTB Elite — maîtres 2400+": "Lumbra OTB Elite — 레이팅 2400 이상 마스터",
  "Lumbra Gigabase OTB — complète": "Lumbra Gigabase OTB — 전체",
  "Parties sur échiquier entre deux joueurs classés au moins 2400 Elo. Télécharge l’archive officielle, puis importe-la ici.": "두 선수 모두 Elo 레이팅이 2400 이상인 오프라인 대국입니다. 공식 압축 파일을 다운로드한 다음 여기로 가져오세요.",
  "Collection complète des parties sur échiquier. L’import et l’indexation peuvent prendre plusieurs heures et beaucoup d’espace disque.": "오프라인 대국 전체 모음입니다. 가져오기와 색인 작업에 몇 시간과 많은 디스크 공간이 필요할 수 있습니다.",
  "Gratuit avec attribution pour un usage non commercial. Une licence distincte est nécessaire pour un usage commercial.": "출처를 표시한 비상업적 이용은 무료입니다. 상업적 이용에는 별도 라이선스가 필요합니다.",
  "Vérification et copie de l’archive Lumbra": "Lumbra 압축 파일 확인 및 복사 중",
  "Lecture de l’archive Lumbra": "Lumbra 압축 파일 읽는 중",
  "Décompression du PGN Lumbra": "Lumbra PGN 압축 해제 중",
  "Ajout de la base Lumbra à la bibliothèque": "라이브러리에 Lumbra 데이터베이스 추가 중",
  "Préparation de la base Lumbra": "Lumbra 데이터베이스 준비 중",
  "Cette base Lumbra est déjà installée": "이 Lumbra 데이터베이스는 이미 설치되어 있습니다",
  "Base Lumbra disponible": "Lumbra 데이터베이스 준비 완료",
  "7-Zip n’est pas détecté sur le serveur. Installe-le pour importer une archive .7z, ou fournis un PGN déjà extrait.": "서버에서 7-Zip을 찾을 수 없습니다. .7z 압축 파일을 가져오려면 설치하거나, 이미 압축을 푼 PGN 파일을 사용하세요.",
  "Installe 7-Zip sur le serveur, ou décompresse l’archive et importe directement son fichier PGN.": "서버에 7-Zip을 설치하거나 압축을 푼 뒤 PGN 파일을 직접 가져오세요.",
  "Bonus dans 1 coup : +{seconds} s": "1수 후 보너스: +{seconds}초",
  "Seule la résolution sans erreur compte pour le classement. La reconstruction est une statistique secondaire, sans effet sur la cote. Une erreur, une révélation ou un abandon avant la fin de la solution peut faire baisser la cote.": "실수 없이 끝까지 푼 경우에만 레이팅 점수를 얻습니다. 포지션 재구성은 레이팅에 영향을 주지 않는 보조 통계입니다. 풀이를 마치기 전에 실수하거나 해답을 보거나 포기하면 레이팅이 내려갈 수 있습니다.",
  "Classé : seule la résolution sans erreur compte. La reconstruction ne change pas la cote.": "레이팅 반영: 실수 없이 푼 경우에만 점수를 얻습니다. 포지션 재구성은 레이팅에 영향을 주지 않습니다.",
  "Solution sans erreur.": "실수 없이 해결했습니다.",
  "Aucun point gagné : une solution complète sans erreur est requise.": "획득한 점수 없음: 실수 없이 끝까지 풀어야 합니다.",
  "Passer la reconstruction": "포지션 재구성 건너뛰기",
  "Position départ": "시작 포지션",
  "Position initiale standard": "표준 시작 포지션",
  "Statistique secondaire : cette étape ne change ni la réussite du puzzle ni la cote.": "보조 통계: 이 단계는 퍼즐 성공 여부나 레이팅에 영향을 주지 않습니다.",
  "Position finale · statistique secondaire": "최종 포지션 · 보조 통계",
  "Non effectuée": "시도하지 않음",
  "Cette séance expérimentale est archivée. Ses résultats restent dans l’historique.": "이 실험적 세션은 보관되었습니다. 결과는 기록에 남아 있습니다.",
  "Guess the Move Mix": "Guess the Move Mix",
