  "Seules les bases cochées apparaissent dans le menu Deviner le coup.": "선택한 데이터베이스만 다음 수 맞히기 메뉴에 표시됩니다.",
  "Retour aux bases": "데이터베이스로 돌아가기",
  "{count} partie": "대국 {count}개",
  "Et {count} autres…": "외 {count}개…",
  "Les parties sélectionnées seront supprimées de cette base de référence. Le fichier PGN original est conservé. Cette action ne peut pas être annulée.": "선택한 대국이 이 참고 데이터베이스에서 삭제됩니다. 원본 PGN 파일은 유지됩니다. 이 작업은 되돌릴 수 없습니다.",
  "Les parties seront copiées dans la base choisie, puis supprimées de cette base de référence. Le fichier PGN original est conservé.": "대국을 선택한 데이터베이스에 복사한 다음 이 참고 데이터베이스에서 삭제합니다. 원본 PGN 파일은 유지됩니다.",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires.": "모든 수, 변형 및 해설이 포함된 독립된 복사본을 만듭니다.",
  "{count} partie supprimée.": "대국 {count}개를 삭제했습니다.",
  "{count} parties supprimées.": "대국 {count}개를 삭제했습니다.",
  "{count} partie dupliquée.": "대국 {count}개의 복사본을 만들었습니다.",
  "{count} parties dupliquées.": "대국 {count}개의 복사본을 만들었습니다.",
  "{count} partie déplacée.": "대국 {count}개를 이동했습니다.",
  "{count} parties déplacées.": "대국 {count}개를 이동했습니다.",
  "Sélectionne des parties pour les dupliquer, les déplacer ou les supprimer. Pour les annoter ou les réviser, duplique-les dans une base personnelle. L’explorer et la recherche de positions utilisent la ligne principale des parties de référence.": "복사, 이동 또는 삭제할 대국을 선택하세요. 주석을 달거나 복습하려면 개인 데이터베이스로 복사하세요. 탐색기와 포지션 검색은 참고 대국의 메인라인을 사용합니다.",
  "Reprends la partie pour continuer.": "계속하려면 대국을 재개하세요.",
  "Reconstruction non effectuée": "포지션 재구성을 건너뜀",
  "Tout réviser": "모두 복습",
  "Tout apprendre": "모두 배우기",
  "Un lancement attend une confirmation. Réessaie le même choix pour retrouver tes cartes.": "세션 시작을 확인하는 중입니다. 같은 항목을 다시 선택하면 카드를 복구할 수 있습니다.",
  "Réviser / Apprendre": "복습 / 배우기",
  "Cartes à travailler": "학습할 카드",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les révisions dues passent avant les nouvelles cartes.": "개인 실수와 실패한 퍼즐은 활성 데이터베이스에 이미 있는 연습 문제에서 가져옵니다. 복습할 시기가 된 카드를 새 카드보다 먼저 학습합니다.",
  "La sélection ne correspond pas au bloc du programme.": "선택한 항목이 프로그램 블록과 일치하지 않습니다.",
  "Réviser seulement": "복습만",
  "Apprendre seulement": "새 카드 학습만",
  "Réviser + Apprendre": "복습 + 새 카드 학습",
