  "Les révisions dues passent avant les nouvelles cartes.": "복습할 시기가 된 카드를 새 카드보다 먼저 학습합니다.",
  "Aucune nouvelle carte": "새 카드 없음",
  "Toutes les cartes disponibles ont déjà été travaillées.": "사용 가능한 카드는 모두 이미 학습했습니다.",
  "Aucune révision due. Tu peux apprendre de nouvelles cartes.": "지금 복습할 카드는 없습니다. 새 카드를 학습할 수 있습니다.",
  "Espacement des révisions": "복습 간격",
  " nouvelles cartes disponibles pour apprendre.": " 개의 새 카드를 학습할 수 있습니다.",
  "Le calendrier et les séries de jours utilisent la même journée d’étude.": "달력과 연속 학습일 계산에는 같은 학습일 기준을 사용합니다.",
  "Ces objectifs proposent une pause sans modifier les échéances. Tu peux les adapter au lancement.": "이 목표는 복습 예정일을 바꾸지 않고 휴식을 제안합니다. 시작할 때 조정할 수 있습니다.",
  "Choisis les bases à mettre à jour avec les valeurs globales Manqué, Difficile, Bien et Facile. Les échéances et l’historique restent conservés.": "다시, 어려움, 좋음, 쉬움의 공통 설정을 적용할 데이터베이스를 선택하세요. 복습 예정일과 기록은 유지됩니다.",
